-- Reviews typed in by the admins (admin: Reviews). Starts with five Google reviews, written around March 2026.
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('reviews', '[{"id":"r1","enabled":true,"name":"denisa furdui","rating":5,"text":"We had an amazing experience with our guide from Just Love Tour in Mauritius! He was extremely friendly, professional, and very knowledgeable. He shared fascinating information about the island’s history, culture, and beautiful locations, making every stop even more special.","date":"2026-03","source":"google"},{"id":"r2","enabled":true,"name":"Renata Bhujun","rating":5,"text":"Luv is amazing driver and guide in one. Highly recommend 👍👍👍🇲🇺🇲🇺🇲🇺","date":"2026-03","source":"google"},{"id":"r3","enabled":true,"name":"F.A","rating":5,"text":"Nous avons eu la chance de découvrir l’île avec Just Love Tour et c’était tout simplement parfait 🌊\nAccueil chaleureux, service au top et plein de belles surprises tout au long de la journée. On sent la passion pour Maurice et l’envie de faire plaisir.\nMerci pour cette magnifique journée, on recommande les yeux fermé","date":"2026-03","source":"google"},{"id":"r4","enabled":true,"name":"Nicolas dal gobbo","rating":5,"text":"Nous avons eu la chance de découvrir l''île Maurice pour notre anniversaire de mariage. Nous avons pu y découvrir des endroits incroyables et magnifiques mais aussi rencontrer des personnes incroyables et tellement accueillantes ! Je recommande fortement Just love guide pour vous faire visiter cette île incroyable, ce guide est tres chaleureux et très a l''écoute de ce que vous lui demanderez.","date":"2026-03","source":"google"},{"id":"r5","enabled":true,"name":"Laurie Anne","rating":5,"text":"Merci pour ces belles découvertes de l''île Maurice 🙏 notre guide a pris le temps pour nous avec mes difficultés de marche suite à un accident en France avant de venir, il nous a expliqué plein de choses sur l''histoire de l''île, les coutumes, les paysages... C''était riche et très clair ! Et tout ceci avec une pointe d''humour qui nous a donné envie de faire nos excursions en sa compagnie ! Les excursions était PARFAITES ! 😍","date":"2026-03","source":"google"}]', 1794902400000);
